"""Regenerate the browser schema using only the public Python package."""

import argparse
import json
from pathlib import Path

from ygaraty.backends.webgpu.operations import schema

PACKAGE = Path(__file__).resolve().parents[2]
DESTINATION = PACKAGE / "ygaraty/backends/webgpu/browser/inference_schema.mts"


def render() -> str:
    template = Path(__file__).with_name("inference_types.mts.in").read_text()
    # Preserve the generated artifact bytes during this extraction.
    return (
        "// Generated by scripts/codegen/inference_schema.py; do not edit.\n"
        "export const INFERENCE_SCHEMA = "
        + json.dumps(schema(), indent=2)
        + " as const;\n"
        + template
    )


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = render()
    if args.check:
        if DESTINATION.read_text() != output:
            parser.exit(1, "Stale public inference schema\n")
    else:
        DESTINATION.write_text(output)


if __name__ == "__main__":
    main()
